def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            base = v
            prerelease_parts = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre1, pre2):
        # None means no pre-release (higher precedence)
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # no pre-release sorts after pre-release
        if pre2 is None:
            return -1  # pre-release sorts before no pre-release

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric - compare numerically
                result = int(id1) - int(id2)
                if result != 0:
                    return -1 if result < 0 else 1
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric - compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer identifiers sort first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    # Create list with (parsed_version, original_index, original_string)
    indexed_versions = []
    for i, v in enumerate(versions):
        parsed = parse_version(v)
        indexed_versions.append((parsed, i, v))

    # Sort with stable sort
    def sort_key(item):
        parsed, orig_idx, _ = item
        major, minor, patch, prerelease = parsed

        # Create tuple for sorting
        # For pre-release comparison, we need a sortable representation
        if prerelease is None:
            pre_tuple = (1,)  # No pre-release sorts after pre-release
        else:
            pre_parts = []
            for part in prerelease:
                if part.isdigit():
                    pre_parts.append((0, int(part)))  # Numeric sorts first
                else:
                    pre_parts.append((1, part))  # Non-numeric sorts after
            pre_tuple = (0, tuple(pre_parts), len(prerelease))

        return (major, minor, patch, pre_tuple, orig_idx)

    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for _, _, v in sorted_versions]

